INSERT INTO products (sku, slug, name, tagline, category_id, price, original_price, rating, review_count, description, badge, stock, accent) VALUES
('ELV-AUD-001', 'vanta-studio-headphones', 'Vanta Studio Headphones', 'Studio headphones with adaptive noise cancellation and balanced, detailed sound.', (SELECT id FROM categories WHERE slug = 'audio'), 549, 629, 4.8, 412, 'Vanta Studio blends adaptive noise cancellation, low-distortion carbon drivers, and breathable memory foam into a clean aluminum frame built for long work sessions and late-night listening.', 'Best Seller', 18, '#7dd3fc'),
('ELV-AUD-002', 'cove-spatial-speaker', 'Cove Spatial Speaker', 'Room-filling sound in a compact speaker that calibrates to your space.', (SELECT id FROM categories WHERE slug = 'audio'), 429, NULL, 4.7, 239, 'Cove Spatial Speaker uses self-tuning room calibration and a 360-degree acoustic lens to deliver balanced, immersive sound from a compact wireless body.', NULL, 16, '#7dd3fc'),
('ELV-AUD-003', 'echo-anc-earbuds', 'Echo ANC Earbuds', 'Compact wireless earbuds with adaptive ANC and clear voice pickup.', (SELECT id FROM categories WHERE slug = 'audio'), 299, NULL, 4.6, 318, 'Echo ANC Earbuds use pressure-relief vents, six beamforming microphones, and adaptive cancellation to keep calls and music clear on commutes and flights.', 'New', 34, '#7dd3fc'),
('ELV-AUD-004', 'pulse-soundbar', 'Pulse Soundbar', 'Low-profile home soundbar tuned for dialog, music, and cinema.', (SELECT id FROM categories WHERE slug = 'audio'), 699, NULL, 4.6, 167, 'Pulse Soundbar combines a center dialog array, side-firing drivers, and automatic room correction in a slim enclosure built for modern living rooms.', NULL, 12, '#7dd3fc'),
('ELV-AUD-005', 'cove-desktop-speaker', 'Cove Desktop Speaker', 'Nearfield desktop speaker with balanced sound for focused work.', (SELECT id FROM categories WHERE slug = 'audio'), 249, NULL, 4.3, 94, 'Cove Desktop Speaker brings a tuned nearfield driver, weighted acoustic base, and simple USB-C audio to compact workstations without crowding the desk.', NULL, 28, '#7dd3fc'),
('ELV-AUD-006', 'pulse-home-speaker', 'Pulse Home Speaker', 'Wireless home speaker with deep bass and room-aware tuning.', (SELECT id FROM categories WHERE slug = 'audio'), 579, NULL, 4.7, 201, 'Pulse Home Speaker fills larger rooms with a dual-driver array, adaptive bass control, and multi-room pairing that stays simple to set up.', 'Editor''s Pick', 19, '#7dd3fc'),
('ELV-AUD-007', 'cove-portable-speaker', 'Cove Portable Speaker', 'Compact wireless speaker with weather resistance and all-day battery.', (SELECT id FROM categories WHERE slug = 'audio'), 279, NULL, 4.4, 142, 'Cove Portable Speaker brings balanced outdoor sound to desks, hotel rooms, and weekend bags with a reinforced shell, passive radiator, and simple USB-C charging.', NULL, 25, '#7dd3fc'),
('ELV-AUD-008', 'vanta-max-headphones', 'Vanta Max Headphones', 'Over-ear wireless headphones with extended battery and wide staging.', (SELECT id FROM categories WHERE slug = 'audio'), 649, NULL, 4.8, 188, 'Vanta Max expands the Vanta headphone platform with larger drivers, stronger isolation, and a wider soundstage for travel, mixing, and deep listening.', 'Limited', 9, '#7dd3fc'),
('ELV-AUD-009', 'vanta-dac-amp', 'Vanta DAC Amp', 'Desktop DAC and headphone amplifier for detailed wired listening.', (SELECT id FROM categories WHERE slug = 'audio'), 349, NULL, 4.6, 128, 'Vanta DAC Amp brings high-resolution decoding, a low-noise headphone stage, and a machined volume dial to desks where precise wired listening matters.', NULL, 21, '#7dd3fc'),
('ELV-AUD-010', 'pulse-wireless-turntable', 'Pulse Wireless Turntable', 'Belt-drive turntable with wireless streaming and precise tracking.', (SELECT id FROM categories WHERE slug = 'audio'), 499, NULL, 4.5, 87, 'Pulse Wireless Turntable pairs a damped belt-drive platter and factory-aligned cartridge with lossless wireless streaming to Cove, Pulse, and Vanta audio products.', 'New', 13, '#7dd3fc'),
('ELV-WEA-001', 'solace-watch', 'Solace Watch', 'Titanium smartwatch for training, travel, and recovery.', (SELECT id FROM categories WHERE slug = 'wearables'), 799, NULL, 4.7, 286, 'Solace Watch pairs an always-on microLED display with dual-frequency GPS, recovery metrics, and a lightweight titanium case built for daily wear.', 'New', 11, '#a78bfa'),
('ELV-WEA-002', 'solace-fitness-band', 'Solace Fitness Band', 'Lightweight fitness band for training, sleep, and daily recovery.', (SELECT id FROM categories WHERE slug = 'wearables'), 179, NULL, 4.4, 214, 'Solace Fitness Band tracks heart rate, sleep stages, oxygen trends, and workout strain in a slim band designed for comfortable 24-hour wear.', NULL, 38, '#a78bfa'),
