('ELV-WEA-005', 'solace-sport-watch', 'Solace Sport Watch', 'Durable sport watch with mapping, training plans, and recovery data.', (SELECT id FROM categories WHERE slug = 'wearables'), 499, NULL, 4.3, 119, 'Solace Sport Watch adds route mapping, structured workouts, hill pacing, and recovery guidance in a lighter case for runners and cyclists.', NULL, 21, '#a78bfa'),
