('ELV-WEA-008', 'orbit-smart-ring', 'Orbit Smart Ring', 'Ceramic smart ring for activity, sleep, and discreet notifications.', (SELECT id FROM categories WHERE slug = 'wearables'), 299, NULL, 4.7, 102, 'Orbit Smart Ring adds activity tracking, sleep insights, and discreet notification taps to a ceramic band designed for all-day wear.', NULL, 27, '#a78bfa'),
('ELV-WEA-009', 'vertex-smart-glasses', 'Vertex Smart Glasses', 'Lightweight smart glasses with open-ear audio and hands-free capture.', (SELECT id FROM categories WHERE slug = 'wearables'), 449, NULL, 4.3, 76, 'Vertex Smart Glasses combine polarized lenses, open-ear speakers, touch controls, and a quick-capture camera for travel notes, calls, and everyday navigation.', 'New', 19, '#a78bfa'),
