('ELV-PHO-007', 'prism-zoom-lens', 'Prism Zoom Lens', 'Weather-sealed zoom lens with quiet autofocus and close-focus detail.', (SELECT id FROM categories WHERE slug = 'photography'), 849, NULL, 4.5, 72, 'Prism Zoom Lens covers everyday focal lengths with constant aperture control, quiet linear autofocus, and close-focus detail for stills and video.', NULL, 20, '#f4f0e8'),
