('ELV-PHO-010', 'prism-camera-gimbal', 'Prism Camera Gimbal', 'Three-axis gimbal with smart follow modes for cameras and phones.', (SELECT id FROM categories WHERE slug = 'photography'), 449, NULL, 4.5, 71, 'Prism Camera Gimbal stabilizes Prism cameras across three axes with quiet motors, smart follow modes, and a fold-flat frame sized for travel bags.', NULL, 12, '#f4f0e8'),
